// ===== FETCH POST PERFORMANCE =====
// Gets latest metrics for all posts

const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];

// Filter posts from last 30 days
const thirtyDaysAgo = new Date();
thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

const activePosts = posts.filter(p => new Date(p.createdAt) > thirtyDaysAgo);

// Prepare data for each post to check
const postChecks = activePosts.map(post => ({
  postId: post.id,
  hook: post.hook,
  createdAt: post.createdAt,
  abTestId: post.abTestId,
  currentViews: post.views,
  currentLikes: post.likes,
  currentComments: post.comments,
  currentSaves: post.saves,
  currentShares: post.shares
}));

return [{
  json: {
    postChecks,
    totalPosts: posts.length,
    activePosts: activePosts.length
  }
}];

// ===== SCRAPE INSTAGRAM METRICS =====
// Uses browser to check actual post performance

const input = $input.first().json;
const { postChecks } = input;

// For each post, generate a browser task to scrape metrics
const scrapeTasks = postChecks.map(post => ({
  postId: post.postId,
  // Instagram post URL pattern
  url: `https://www.instagram.com/p/${post.postId}/`,
  metricsToCollect: [
    'view_count',
    'like_count', 
    'comment_count',
    'save_count',
    'share_count',
    'reach',
    'impressions'
  ]
}));

return [{
  json: {
    ...input,
    scrapeTasks
  }
}];

// ===== ANALYZE PERFORMANCE =====
// Compares metrics, detects trends, triggers alerts

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];

const analysis = {
  alerts: [],
  insights: [],
  viralDetected: false,
  flopDetected: false,
  recommendations: []
};

for (const post of posts) {
  const prevViews = post.views || 0;
  const currentViews = post.currentViews || 0;
  const viewGrowth = currentViews - prevViews;
  const hoursSincePosted = (Date.now() - new Date(post.createdAt).getTime()) / (1000 * 60 * 60);

  // ===== VIRAL DETECTION =====
  if (currentViews > 10000 && hoursSincePosted < 24) {
    analysis.viralDetected = true;
    analysis.alerts.push({
      type: 'VIRAL',
      priority: 'HIGH',
      postId: post.id,
      message: `🔥🔥🔥 VIRAL ALERT! Post "${post.hook}" hit ${currentViews} views in ${Math.round(hoursSincePosted)} hours!`,
      views: currentViews,
      growth: viewGrowth
    });
  }

  if (currentViews > 50000 && hoursSincePosted < 48) {
    analysis.alerts.push({
      type: 'MEGA_VIRAL',
      priority: 'CRITICAL',
      postId: post.id,
      message: `🚀🚀🚀 MEGA VIRAL! "${post.hook}" - ${currentViews} views in ${Math.round(hoursSincePosted)}h! Time to monetize!`,
      views: currentViews
    });
  }

  if (currentViews > 100000) {
    analysis.alerts.push({
      type: 'MONETIZE_READY',
      priority: 'CRITICAL',
      postId: post.id,
      message: `💰 MONETIZATION ALERT! "${post.hook}" hit ${currentViews} views! Your audience is ready. Let's discuss products!`
    });
  }

  // ===== FLOP DETECTION =====
  if (hoursSincePosted > 24 && currentViews < 500) {
    analysis.flopDetected = true;
    analysis.alerts.push({
      type: 'FLOP',
      priority: 'MEDIUM',
      postId: post.id,
      message: `⚠️ Post "${post.hook}" is underperforming (${currentViews} views in ${Math.round(hoursSincePosted)}h). Analyzing why...`
    });

    // Auto-diagnose flop reasons
    analysis.insights.push({
      type: 'FLOP_DIAGNOSIS',
      postId: post.id,
      possibleReasons: [
        'Hook not strong enough - try curiosity gap',
        'Posted at wrong time',
        'Content not resonating with audience',
        'Hashtags not reaching right people',
        'Design not eye-catching enough',
        'Caption too long/short',
        'No clear CTA'
      ]
    });
  }

  // ===== ENGAGEMENT ANALYSIS =====
  if (currentViews > 0) {
    const engagementRate = ((post.likes + post.comments + post.saves) / currentViews * 100).toFixed(2);

    if (engagementRate > 5) {
      analysis.insights.push({
        type: 'HIGH_ENGAGEMENT',
        postId: post.id,
        message: `Great engagement (${engagementRate}%) on "${post.hook}". Double down on this style!`,
        rate: engagementRate
      });
    }

    if (post.saves > post.likes * 0.1) {
      analysis.insights.push({
        type: 'HIGH_SAVES',
        postId: post.id,
        message: `High save ratio on "${post.hook}" — this content is valuable! Create similar content.`
      });
    }
  }

  // ===== A/B TEST ANALYSIS =====
  if (post.abTestId) {
    const abGroup = posts.filter(p => p.abTestId === post.abTestId);
    if (abGroup.length > 1) {
      const bestPerforming = abGroup.reduce((best, p) => (p.views > best.views) ? p : best);
      analysis.insights.push({
        type: 'AB_TEST_RESULT',
        testId: post.abTestId,
        winner: bestPerforming.id,
        winningHook: bestPerforming.hook,
        message: `A/B Test Result: "${bestPerforming.hook}" outperformed with ${bestPerforming.views} views`
      });
    }
  }
}

// ===== GROWTH TREND ANALYSIS =====
const recentPosts = posts.filter(p => {
  const daysSince = (Date.now() - new Date(p.createdAt).getTime()) / (1000 * 60 * 60 * 24);
  return daysSince <= 7;
});

const avgViewsRecent = recentPosts.reduce((sum, p) => sum + (p.views || 0), 0) / (recentPosts.length || 1);
const olderPosts = posts.filter(p => {
  const daysSince = (Date.now() - new Date(p.createdAt).getTime()) / (1000 * 60 * 60 * 24);
  return daysSince > 7 && daysSince <= 14;
});
const avgViewsOlder = olderPosts.reduce((sum, p) => sum + (p.views || 0), 0) / (olderPosts.length || 1);

if (avgViewsRecent > avgViewsOlder * 1.5) {
  analysis.insights.push({
    type: 'GROWTH_TREND',
    message: `📈 GROWTH DETECTED! This week's posts averaging ${Math.round(avgViewsRecent)} views vs ${Math.round(avgViewsOlder)} last week. Keep doing what you're doing!`
  });
} else if (avgViewsRecent < avgViewsOlder * 0.7) {
  analysis.insights.push({
    type: 'DECLINE_TREND',
    message: `📉 Views declining. Time to shake things up — new hooks, new format, or new posting time.`
  });
}

// ===== STORE ANALYSIS =====
if (!staticData.analytics) staticData.analytics = [];
staticData.analytics.push({
  timestamp: new Date().toISOString(),
  analysis,
  totalPosts: posts.length,
  avgViews: avgViewsRecent
});

return [{
  json: {
    analysis,
    posts,
    chatId: input.chatId || staticData.chatId
  }
}];

// ===== FORMAT ALERT MESSAGES =====

const input = $input.first().json;
const { analysis, chatId } = input;

const messages = analysis.alerts.map(alert => {
  let emoji = '📊';
  let priority = '';

  switch(alert.type) {
    case 'VIRAL':
      emoji = '🔥';
      priority = '🚨 URGENT';
      break;
    case 'MEGA_VIRAL':
      emoji = '🚀';
      priority = '🚨🚨 CRITICAL';
      break;
    case 'MONETIZE_READY':
      emoji = '💰';
      priority = '💎 MONETIZATION TIME';
      break;
    case 'FLOP':
      emoji = '⚠️';
      priority = '📋 ACTION NEEDED';
      break;
  }

  return `${emoji} *${priority}*\n\n${alert.message}`;
});

// Add insights
const insightMessages = analysis.insights.map(insight => {
  return `💡 *Insight:* ${insight.message}`;
});

const fullMessage = [...messages, ...insightMessages].join('\n\n---\n\n');

return [{
  json: {
    chatId,
    message: fullMessage,
    hasViral: analysis.viralDetected,
    hasFlop: analysis.flopDetected
  }
}];

// ===== AUTO-ADJUST STRATEGY =====
// When posts flop, automatically research and adjust

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');

if (input.hasFlop) {
  // Trigger additional research
  const niche = staticData.niche;

  // Research what's currently working
  const researchQueries = [
    `${niche} viral content this week`,
    `${niche} trending hooks`,
    `${niche} best performing posts today`,
    `what's working on instagram ${niche} 2026`
  ];

  // Adjust content strategy
  if (!staticData.strategyAdjustments) staticData.strategyAdjustments = [];
  staticData.strategyAdjustments.push({
    timestamp: new Date().toISOString(),
    reason: 'Post underperformance detected',
    action: 'Increased research frequency + new hook testing',
    queries: researchQueries
  });
}

if (input.hasViral) {
  // Double down on viral content
  if (!staticData.viralPatterns) staticData.viralPatterns = [];
  staticData.viralPatterns.push({
    timestamp: new Date().toISOString(),
    action: 'Identified viral pattern - will replicate'
  });
}

return [{
  json: {
    adjusted: input.hasFlop || input.hasViral,
    chatId: input.chatId
  }
}];

// ===== GENERATE ANALYTICS REPORT =====

const input = $input.first().json;
const staticData = $getWorkflowStaticData('global');
const posts = staticData.posts || [];

// Calculate stats
const totalViews = posts.reduce((sum, p) => sum + (p.views || 0), 0);
const totalLikes = posts.reduce((sum, p) => sum + (p.likes || 0), 0);
const totalComments = posts.reduce((sum, p) => sum + (p.comments || 0), 0);
const totalSaves = posts.reduce((sum, p) => sum + (p.saves || 0), 0);
const avgViews = totalViews / (posts.length || 1);

// Top performing posts
const topPosts = [...posts].sort((a, b) => (b.views || 0) - (a.views || 0)).slice(0, 5);

// Worst performing
const worstPosts = [...posts].sort((a, b) => (a.views || 0) - (b.views || 0)).slice(0, 3);

// Best hooks
const hookPerformance = {};
for (const post of posts) {
  if (!hookPerformance[post.hook]) hookPerformance[post.hook] = 0;
  hookPerformance[post.hook] += post.views || 0;
}
const bestHooks = Object.entries(hookPerformance)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

const report = `📊 *ANALYTICS DASHBOARD*\n\n` +
  `📈 *Overview:*\n` +
  `📝 Total Posts: ${posts.length}\n` +
  `👁️ Total Views: ${totalViews.toLocaleString()}\n` +
  `❤️ Total Likes: ${totalLikes.toLocaleString()}\n` +
  `💬 Total Comments: ${totalComments.toLocaleString()}\n` +
  `🔖 Total Saves: ${totalSaves.toLocaleString()}\n` +
  `📊 Avg Views/Post: ${Math.round(avgViews).toLocaleString()}\n\n` +
  `🏆 *Top Performing:*\n` +
  topPosts.map((p, i) => `${i+1}. "${p.hook}" — ${p.views} views`).join('\n') +
  `\n\n🎣 *Best Hooks:*\n` +
  bestHooks.map((h, i) => `${i+1}. "${h[0]}" — ${h[1]} total views`).join('\n') +
  `\n\n⚠️ *Needs Improvement:*\n` +
  worstPosts.map((p, i) => `${i+1}. "${p.hook}" — ${p.views} views`).join('\n');

return [{
  json: {
    chatId: input.chatId,
    report
  }
}];
